207	        this.possibleDuplicateOf = possibleDuplicateOf;
208	    }
209	
210	    /**
211	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
212	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
213	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure (days since
214	     * {@link #getRegistrationDate() registrationDate}) exceeds 365. A newly created owner has zero
215	     * tenure, so a new owner can score at most 5 points.
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        int points = 0;
220	        boolean hasEmail = this.email != null && !this.email.isBlank();
221	        if (hasEmail) {
222	            points += 2;
223	        }
224	        if (this.namesakeCount != null && this.namesakeCount == 0) {
225	            points += 1;
226	        }
227	        if (this.householdSize != null && this.householdSize >= 3) {
228	            points += 2;
229	        }
230	        if (this.registrationDate != null
231	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
232	            points += 3;
233	        }
234	        return points;
235	    }
236	
237	    /**
238	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
239	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
240	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
241	     */
242	    @Transient
243	    public Integer getMembershipLevel() {
244	        int points = getMembershipPoints();
245	        if (points <= 1) {
246	            return 1;
247	        }
248	        if (points <= 3) {
249	            return 2;
250	        }
251	        if (points <= 5) {
252	            return 3;
253	        }
254	        return 4;
255	    }
256	
257	    /**
258	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
259	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
260	     * ignored). {@code null} when the owner has no customerCode.
261	     */
262	    @Transient
263	    public Integer getCheckDigit() {
264	        if (this.customerCode == null) {
265	            return null;
266	        }
267	        int sum = 0;
268	        boolean dbl = true;
269	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
270	            char c = this.customerCode.charAt(i);
271	            if (c < '0' || c > '9') {
272	                continue;
273	            }
274	            int d = c - '0';
275	            if (dbl) {
276	                d *= 2;
277	                if (d > 9) {
278	                    d -= 9;
279	                }
280	            }
281	            sum += d;
282	            dbl = !dbl;
283	        }
284	        return (10 - (sum % 10)) % 10;
285	    }
286	
287	    /**
288	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
289	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
290	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
291	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
292	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
293	     * yields {@code 'UNKNOWN'}.
294	     */
295	    @Transient
296	    public String getLocality() {
297	        String byPostcode = regionForPostcode(this.postcode);
298	        if (byPostcode != null) {
299	            return byPostcode;
300	        }
301	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
302	    }
303	
304	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
305	    private static String regionForPostcode(String postcode) {
306	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
307	            return null;
308	        }
309	        int value = Integer.parseInt(postcode);
310	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
311	            int[] range = entry.getValue();
312	            if (value >= range[0] && value <= range[1]) {
313	                return entry.getKey();
314	            }
315	        }
316	        return null;
317	    }
318	
319	    /**
320	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
321	     * time: the country code, a space, then the national digits grouped in threes (e.g.
322	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
323	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
324	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
325	     * has no telephone or it is not a well-formed E.164 number.
326	     */
327	    @Transient
328	    public String getTelephoneDisplay() {
329	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
330	            return null;
331	        }
332	        String digits = this.telephone.substring(1); // drop the leading '+'
333	        String countryCode = countryCodeOf(digits);
334	        String national = digits.substring(countryCode.length());
335	        StringBuilder display = new StringBuilder("+").append(countryCode);
336	        display.append(' ');
337	        for (int i = 0; i < national.length(); i++) {
338	            if (i > 0 && i % 3 == 0) {
339	                display.append(' ');
340	            }
341	            display.append(national.charAt(i));
342	        }
343	        return display.toString();
344	    }
345	
346	    /**
347	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
348	     * are matched longest-first; any other number falls back to a two-digit country code.
349	     */
350	    private static String countryCodeOf(String digits) {
351	        for (String code : KNOWN_COUNTRY_CODES) {
352	            if (digits.startsWith(code) && digits.length() > code.length()) {
353	                return code;
354	            }
355	        }
356	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
357	    }
358	
359	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
360	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
361	
362	    /**
363	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
364	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
365	     */
366	    @Transient
367	    public String getContactPreference() {
368	        boolean hasEmail = this.email != null && !this.email.isBlank();
369	        return hasEmail ? "EMAIL" : "PHONE";
370	    }
371	
372	    /**
373	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
374	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
375	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
376	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
377	     */
378	    @Transient
379	    public String getAgeBand() {
380	        if (this.birthDate == null || this.registrationDate == null) {
381	            return null;
382	        }
383	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
384	        if (years < 18) {
385	            return "MINOR";
386	        }
387	        if (years < 65) {
388	            return "ADULT";
389	        }
390	        return "SENIOR";
391	    }
392	
393	    /**
394	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
395	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
396	     * the owner has a unique household). All duplicate detection is expressed through this one key:
397	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
398	     * telephone is part of the key, two members of the same household with different telephones have
399	     * different identityKeys and are both allowed.
400	     */
401	    @Transient
402	    public String getIdentityKey() {
403	        String tel = this.telephone == null ? "" : this.telephone;
404	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
405	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
406	        return tel + "|" + mail + "|" + household;
407	    }
408	
409	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
410	    private static final Map<String, String> CITY_REGION =
411	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
412	
413	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
414	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
415	        "NSW", new int[] {2000, 2099},
416	        "VIC", new int[] {3000, 3099},
417	        "QLD", new int[] {4000, 4099});
418	
419	    protected Set<Pet> getPetsInternal() {
420	        if (this.pets == null) {
421	            this.pets = new HashSet<>();
422	        }
423	        return this.pets;
424	    }
425	
426	    protected void setPetsInternal(Set<Pet> pets) {
427	        this.pets = pets;
428	    }
429	
430	    public List<Pet> getPets() {
431	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
432	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
433	        return Collections.unmodifiableList(sortedPets);
434	    }
435	
436	    public void setPets(List<Pet> pets) {
437	        this.pets = new HashSet<>(pets);
438	    }
439	
440	    public void addPet(Pet pet) {
441	        getPetsInternal().add(pet);
442	        pet.setOwner(this);
443	    }
444	
445	    /**
446	     * Return the Pet with the given name, or null if none found for this Owner.
447	     *
448	     * @param name to test
449	     * @return true if pet name is already in use
450	     */
451	    public Pet getPet(String name) {
452	        return getPet(name, false);
453	    }
454	
455	    /**
456	     * Return the Pet with the given name, or null if none found for this Owner.
457	     *
458	     * @param name to test
459	     * @return true if pet name is already in use
460	     */
461	    public Pet getPet(String name, boolean ignoreNew) {
462	        name = name.toLowerCase();
463	        for (Pet pet : getPetsInternal()) {
464	            if (!ignoreNew || !pet.isNew()) {
465	                String compName = pet.getName();
466	                compName = compName.toLowerCase();
467	                if (compName.equals(name)) {
468	                    return pet;
469	                }
470	            }
471	        }
472	        return null;
473	    }
474	
475	    public Pet getPet(Integer petId) {
476	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
477	    }
478	
479	    @Override
480	    public String toString() {
481	        return new ToStringCreator(this)
482	
483	            .append("id", this.getId())
484	            .append("new", this.isNew())
485	            .append("lastName", this.getLastName())
486	            .append("firstName", this.getFirstName())
487	            .append("address", this.address)
488	            .append("city", this.city)
489	            .append("telephone", this.telephone)
490	            .toString();
491	    }
492	}
